// ============================================================
// Parse AI Analysis & Apply Thresholds
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  let analysis;
  try {
    const response = item.json.choices?.[0]?.message?.content || '{}';
    analysis = JSON.parse(response);
  } catch (e) {
    analysis = { fit_score: 0, decision: 'SKIP', explanation: 'Failed to parse AI response' };
  }

  // Apply thresholds
  const fitScore = analysis.fit_score || 0;
  if (fitScore >= 80) analysis.decision = 'APPLY';
  else if (fitScore >= 65) analysis.decision = 'REVIEW';
  else analysis.decision = 'SKIP';

  results.push({
    json: {
      ...item.json,
      analysis: analysis,
      fit_score: fitScore,
      decision: analysis.decision
    }
  });
}

return results;

// ============================================================
// Generate Daily Summary Report
// ============================================================

const allItems = $('Parse Analysis & Apply Thresholds').all();

const summary = {
  date: new Date().toISOString().split('T')[0],
  total_processed: allItems.length,
  apply: allItems.filter(i => i.json.decision === 'APPLY').length,
  review: allItems.filter(i => i.json.decision === 'REVIEW').length,
  skip: allItems.filter(i => i.json.decision === 'SKIP').length,
  strong_matches: allItems
    .filter(i => i.json.decision === 'APPLY')
    .map(i => ({
      title: i.json.job_title,
      company: i.json.company,
      location: i.json.location,
      fit_score: i.json.fit_score,
      url: i.json.linkedin_url
    }))
};

return [{ json: summary }];
